#!/usr/bin/env node
"use strict";

/**
 * The fleet checks' one entry point: the reusable workflow and a repo's
 * release script both call this, so CI and a release read fragments, tags
 * and paths the same way (#1561).
 *
 * Source of truth: the operations repo's `scripts/fleet-checks/`; the shared
 * workflow repo's copy is generated by `publish.sh` and never hand-edited.
 *
 *   cli.js changelog release <tag>   the body of one release; a tag not yet cut
 *                                    renders what would ship if HEAD were tagged
 *   cli.js changelog print [--stream S]
 *   cli.js changelog check --base <ref> [--head <ref>] [--author <login>]
 *                                    reads the PR body from $PR_BODY
 *   cli.js changelog lint            every fragment in the working tree
 *   cli.js dead-paths                the ratchet: per-file counts against
 *                                    the repo's .github/dead-paths-baseline.json, both ways
 *   cli.js dead-paths --write-baseline   record today's counts (adoption, or after a fix)
 *   cli.js dead-paths --all          list every dead path; exit 1 if there is any
 *
 * Common: --root <dir> (default: cwd). Exit 0 clean · 1 findings · 2 could not run.
 *
 * Node only, no dependencies: every fleet repo can run it, whatever it is
 * written in, because the workflow installs Node for it (#1561).
 */

const fs = require("node:fs");
const path = require("node:path");
const cl = require("./changelog.js");
const dp = require("./dead-paths.js");
const { loadConfig, ConfigError } = require("./config.js");

class UsageError extends Error {}

function parseArgs(argv) {
  const pos = [];
  const flags = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith("--")) { pos.push(a); continue; }
    const key = a.slice(2);
    if (["json", "all", "write-baseline"].includes(key)) { flags[key] = true; continue; }
    const v = argv[i + 1];
    if (v === undefined || v.startsWith("--")) throw new UsageError(`--${key} needs a value`);
    flags[key] = v;
    i++;
  }
  return { pos, flags };
}

const inActions = process.env.GITHUB_ACTIONS === "true";
// An annotation lands on the PR's diff view; the escaping is GitHub's workflow-command format.
const esc = (s) => String(s).replace(/%/g, "%25").replace(/\r/g, "%0D").replace(/\n/g, "%0A");
const annotate = (level, msg, file, line) => {
  if (!inActions) return;
  const loc = file ? ` file=${esc(file)}${line ? `,line=${line}` : ""}` : "";
  console.log(`::${level}${loc}::${esc(msg)}`);
};

function changelog(sub, pos, flags, root, cfg) {
  const { streams } = cfg;
  if (sub === "release") {
    const tag = pos[0];
    if (!tag) throw new UsageError("changelog release <tag>");
    const stream = cl.tagStream(tag, streams);
    if (!stream) {
      throw new UsageError(`"${tag}" matches no stream's prefix (${Object.entries(streams).map(([n, s]) => `${n}: ${s.tagPrefix}*`).join(", ")})`);
    }
    const cut = cl.refExists(root, `refs/tags/${tag}`);
    const { entries, problems } = collect(root, cut ? `refs/tags/${tag}` : "HEAD", streams);
    const r = cl.renderRelease(entries, stream, tag, { pending: !cut });
    process.stdout.write(r.text);
    // A release with no fragments warns and still succeeds (PM ruling on #1561):
    // a deploy is never held up by its notes.
    if (r.count === 0) {
      console.error(`warning: ${tag} carries no changelog fragments`);
      annotate("warning", `${tag} carries no changelog fragments`);
    }
    return 0;
  }
  if (sub === "print") {
    if (flags.stream && !streams[flags.stream]) throw new UsageError(`no stream "${flags.stream}" (${Object.keys(streams).join(", ")})`);
    const { entries, tags } = collect(root, "HEAD", streams);
    const legacy = fs.existsSync(path.join(root, "CHANGELOG.md"));
    process.stdout.write(cl.renderChangelog({ entries, tags, streams, only: flags.stream ?? null, legacy }));
    return 0;
  }
  if (sub === "lint") {
    const dir = path.join(root, cl.FRAGMENT_DIR);
    const files = fs.existsSync(dir) ? fs.readdirSync(dir).map((f) => `${cl.FRAGMENT_DIR}/${f}`).filter(cl.isFragmentPath) : [];
    const errors = files.flatMap((f) => cl.parseFragment(f, fs.readFileSync(path.join(root, f), "utf8"), streams).errors);
    for (const e of errors) console.error(`error: ${e}`);
    console.log(`${files.length} fragment(s), ${errors.length} problem(s)`);
    return errors.length ? 1 : 0;
  }
  if (sub === "check") {
    if (!flags.base) throw new UsageError("changelog check --base <ref> [--head <ref>]");
    const head = flags.head ?? "HEAD";
    const changes = cl.prChanges(root, flags.base, head);
    const texts = new Map(changes.filter((c) => c.status !== "D" && cl.isFragmentPath(c.path)).map((c) => [c.path, cl.showAt(root, head, c.path)]));
    const r = cl.evaluatePr({ changes, texts, streams, body: process.env.PR_BODY ?? "", author: flags.author ?? "" });
    for (const n of r.notices) console.log(`note: ${n}`);
    for (const f of r.fragments.filter((x) => x.valid)) console.log(`ok: ${f.path} — ${f.type}, ships ${f.ships.join(", ")}`);
    for (const e of r.errors) { console.error(`error: ${e}`); annotate("error", e, /^changelog\.d\/\S+?\.md/.exec(e)?.[0]); }
    return r.errors.length ? 1 : 0;
  }
  throw new UsageError(`unknown: changelog ${sub ?? ""}`);
}

function collect(root, ref, streams) {
  const out = cl.collect(root, { ref, streams });
  for (const p of out.problems) console.error(`warning: skipped an invalid fragment — ${p}`);
  return out;
}

function deadPaths(flags, root, cfg) {
  const tracked = dp.trackedFiles(root);
  const { docs, code, excused } = dp.selectCorpus(tracked, cfg.deadPaths);
  const { findings, skippedIgnored } = dp.findDeadPaths({
    root, tracked, docs, code,
    linksResolveElsewhere: cfg.deadPaths.linksResolveElsewhere, foreignNames: cfg.deadPaths.foreignNames,
  });
  const live = dp.countsByFile(findings);
  const baselineFile = path.join(root, dp.BASELINE_PATH);
  // The denominator is printed every run: a quiet run over a smaller corpus
  // must not read the same as a clean one (#867).
  const summary = `${findings.length} dead path(s) in ${Object.keys(live).length} file(s) · ${docs.length} docs, ` +
    `${code.length} code files judged · ${excused.length} excused · ${skippedIgnored} gitignored path(s) skipped`;

  if (flags.json) {
    process.stdout.write(`${JSON.stringify({ findings, counts: live, docs: docs.length, code: code.length, excused: excused.length, skippedIgnored }, null, 2)}\n`);
    return 0;
  }
  if (flags["write-baseline"]) {
    // Adoption, and lowering after a fix: the file is regenerated whole, so a
    // hand-edit cannot leave it disagreeing with the tree.
    fs.mkdirSync(path.dirname(baselineFile), { recursive: true });
    fs.writeFileSync(baselineFile, dp.renderBaseline(live));
    console.log(`wrote ${dp.BASELINE_PATH}: ${summary}`);
    return 0;
  }
  const show = (f) => console.log(`  ${f.file}:${f.line} [${f.kind}] ${f.target}\n      → ${f.reason}`);
  if (flags.all) {
    findings.forEach(show);
    console.log(`dead-paths --all: ${summary}`);
    return findings.length ? 1 : 0;
  }

  let baseline = {};
  if (fs.existsSync(baselineFile)) {
    try { baseline = JSON.parse(fs.readFileSync(baselineFile, "utf8")); }
    catch (e) { throw new ConfigError(`${dp.BASELINE_PATH}: not valid JSON (${e.message})`); }
  }
  const { grew, shrank, invalid } = dp.compareToBaseline(live, baseline);
  for (const msg of invalid) { console.error(`error: ${dp.BASELINE_PATH} ${msg}`); annotate("error", msg, dp.BASELINE_PATH); }
  if (grew.length) {
    console.error(`error: new dead paths — a path in a doc or comment that resolves to nothing in this repo. Fix the path;` +
      ` if it names another repo's file, say which repo on the same line.`);
    for (const g of grew) {
      console.error(`${g.file}: ${g.was} recorded, ${g.now} now`);
      for (const f of findings.filter((x) => x.file === g.file)) {
        show(f);
        annotate("error", `${f.target}: ${f.reason} (${g.file} has ${g.now}, the baseline records ${g.was})`, f.file, f.line);
      }
    }
  }
  if (shrank.length) {
    console.error(`error: dead paths were fixed — lower the baseline in this same PR so it stays true:` +
      ` run \`cli.js dead-paths --write-baseline\` and commit ${dp.BASELINE_PATH}.`);
    for (const s of shrank) {
      console.error(`${s.file}: ${s.was} recorded, ${s.now} now`);
      annotate("error", `${s.file}: ${s.was} recorded, ${s.now} now — lower the baseline`, dp.BASELINE_PATH);
    }
  }
  const failed = grew.length + shrank.length + invalid.length > 0;
  console.log(`dead-paths: ${failed ? "FAIL" : "ok"} — ${summary} · baseline ${Object.values(baseline).reduce((a, b) => a + (Number(b) || 0), 0)}`);
  return failed ? 1 : 0;
}

function main(argv) {
  const { pos, flags } = parseArgs(argv);
  const root = path.resolve(flags.root ?? process.cwd());
  const cfg = loadConfig(root);
  const [cmd, sub, ...rest] = pos;
  if (cmd === "changelog") return changelog(sub, rest, flags, root, cfg);
  if (cmd === "dead-paths") return deadPaths(flags, root, cfg);
  throw new UsageError("usage: cli.js changelog <release|print|check|lint> … | cli.js dead-paths …");
}

if (require.main === module) {
  let code;
  try {
    code = main(process.argv.slice(2));
  } catch (e) {
    // "Could not run" is its own exit code so a caller never reads a crash as a finding, or as clean.
    console.error(e instanceof UsageError || e instanceof ConfigError ? `fleet-checks: ${e.message}` : `fleet-checks: could not run — ${e.stack || e}`);
    code = 2;
  }
  process.exitCode = code;
}

module.exports = { main, parseArgs };
